class LoadOnScroll{constructor(e,t){if("string"==typeof e){this.containerId=e,this.contentUrl=t,this.refresh();let o=this;document.addEventListener("scroll",function(e){let t=o.position();o.size().height-20<=t.top&&o.refresh()})}}refresh(){let e=document.createElement("div");e.id="bufferDiv",e.style.display="none",document.body.appendChild(e),e.innerHTML=fetch(this.contentURL).then(e=>e).catch(e=>e),document.getElementById(this.containerId).innerHTML+=e.innerHTML,e.remove()}position(){let e=0,t=0;return"number"==typeof window.scrollY?(e=window.scrollX,t=window.scrollY):document.body&&(document.body.scrollLeft||document.body.scrollTop)?(e=document.body.scrollLeft,t=document.body.scrollTop):document.documentElement&&(document.documentElement.scrollLeft||document.documentElement.scrollTop)&&(e=document.documentElement.scrollLeft,t=document.documentElement.scrollTop),{left:e,top:t}}size(){return{width:Math.max(document.body.scrollWidth,document.documentElement.scrollWidth,document.body.offsetWidth,document.documentElement.offsetWidth,document.body.clientWidth,document.documentElement.clientWidth),height:Math.max(document.body.scrollHeight,document.documentElement.scrollHeight,document.body.offsetHeight,document.documentElement.offsetHeight,document.body.clientHeight,document.documentElement.clientHeight)}}}